WITH base AS (SELECT *, LENGTH(status) AS status_length FROM accounts WHERE customer_id IS NOT NULL AND status NOT IN ('CLOSED', 'FROZEN')) SELECT CASE WHEN status_length >= 82 THEN 'LARGE' ELSE 'SMALL' END AS status_length_tier, customer_id, status, COUNT(*) AS num_rows, MIN(balance) AS min_balance, SIZE(COLLECT_SET(account_type)) AS num_account_types FROM base GROUP BY status_length_tier, customer_id, status ORDER BY customer_id
